import { Question } from '../types';
import { classic, challenge, emoji, italian as italianFactory, quote, rush, slang } from './packFactory';

function italian(question: Omit<Question, 'mode'>): Question;
function italian(id: string, visualQuestion: string, visualContent: string, subjectKey: string, answer: string, distractors: string[], difficulty?: Question['difficulty']): Question;
function italian(questionOrId: Omit<Question, 'mode'> | string, ...args: unknown[]): Question {
  if (typeof questionOrId === 'string') {
    const [question, visualContent, subjectKey, answer, distractors, difficulty] = args as [string, string, string, string, string[], Question['difficulty']?];
    return italianFactory(questionOrId, question, visualContent, subjectKey, answer, distractors, difficulty);
  }
  return {
    ...questionOrId,
    mode: 'image',
    era: 'italian_brainrot',
    eligibleForRush: true,
    eligibleForDaily: true,
    tags: [...(questionOrId.tags ?? []), '2025', 'italian brainrot'],
  };
}

const currentSlang = (question: Omit<Question, 'mode'>): Question => ({
  ...question,
  mode: 'slang',
  era: '2026',
  eligibleForRush: true,
  eligibleForDaily: true,
  tags: [...(question.tags ?? []), '2026', 'slang'],
});

